public class InnerCallAnalyticsCategoryNonTalkTimeFilterFactory(Action<Humidifier.Transcribe.CallAnalyticsCategoryTypes.NonTalkTimeFilter> factoryAction = null) : SubResourceFactory<Humidifier.Transcribe.CallAnalyticsCategoryTypes.NonTalkTimeFilter>
{

    internal InnerCallAnalyticsCategoryRelativeTimeRangeFactory RelativeTimeRangeFactory { get; set; }

    internal InnerCallAnalyticsCategoryAbsoluteTimeRangeFactory AbsoluteTimeRangeFactory { get; set; }

    protected override Humidifier.Transcribe.CallAnalyticsCategoryTypes.NonTalkTimeFilter Create()
    {
        var nonTalkTimeFilterResult = CreateNonTalkTimeFilter();
        factoryAction?.Invoke(nonTalkTimeFilterResult);

        return nonTalkTimeFilterResult;
    }

    private Humidifier.Transcribe.CallAnalyticsCategoryTypes.NonTalkTimeFilter CreateNonTalkTimeFilter()
    {
        var nonTalkTimeFilterResult = new Humidifier.Transcribe.CallAnalyticsCategoryTypes.NonTalkTimeFilter();

        return nonTalkTimeFilterResult;
    }
    public override void CreateChildren(Humidifier.Transcribe.CallAnalyticsCategoryTypes.NonTalkTimeFilter result)
    {
        base.CreateChildren(result);

        result.RelativeTimeRange ??= RelativeTimeRangeFactory?.Build();
        result.AbsoluteTimeRange ??= AbsoluteTimeRangeFactory?.Build();
    }

} // End Of Class

